    Bug 1950280 - Attempt to fix intermittent in browser_deletionFromThreads.js. r=aleca,arschmitz

    The intermittent is caused by the delete action, which deletes the
    currently selected message and then selects the next message. Quickly
    changing folders after deleting a message causes the message not to
    be marked as read intermittently and we could end up with an unexpected
    read status in the final test and fail.

    The patch makes sure that the expected read states are seen, before
    moving on. We could also wait for the `onFolderPropertyFlagChanged`
    event, but `TestUtils.waitForCondition()` seems good enough, as we know
    that next message has to be marked as read eventually.

    Differential Revision: https://phabricator.services.mozilla.com/D239555

diff --git a/mail/test/browser/folder-display/browser_deletionFromThreads.js b/mail/test/browser/folder-display/browser_deletionFromThreads.js
index 8af743aa873..47afd67521b 100644
--- a/mail/test/browser/folder-display/browser_deletionFromThreads.js
+++ b/mail/test/browser/folder-display/browser_deletionFromThreads.js
@@ -91,6 +91,20 @@ const assertReplyCount = async replyCount => {
   await switch_tab();
 };

+async function verify_message_read_status(expected, msg) {
+  const dbView =
+    document.getElementById("tabmail").currentTabInfo.chromeBrowser
+      .contentWindow.gDBView;
+  await TestUtils.waitForCondition(() => {
+    const state = [];
+    for (let i = 0; i < dbView.rowCount; i++) {
+      state.push(dbView.getMsgHdrAt(i).isRead);
+    }
+    // We are comparing two simple arrays, no need to be fancy.
+    return JSON.stringify(expected) == JSON.stringify(state);
+  }, `Message read states should be correct (${msg})`);
+}
+
